{"path":"/work/etl/dedupe.py","content":""""Remove duplicate records, keeping the first occurrence."""

_DICT = dict
_LIST = list
_TUPLE = tuple


def _canon(o):
    """Return a hashable value that is equal to (via ==) the canonical form
    of any JSON-like value: dicts -> tuples of (key, canonical value) pairs,
    lists/tuples -> tuples, everything else (primitives) unchanged.

    Values are never mutated; keys may be unhashable (e.g. lists or dicts).
    """
    if isinstance(o, _DICT):
        return _TUPLE((k, _canon(v)) for k, v in o.items())
    if isinstance(o, (_LIST, _TUPLE)):
        return _TUPLE(_canon(v) for v in o)
    return o


def dedupe(records, key=None):
    seen = set()
    out = []
    for r in records:
        k = key(r) if key else r
        if k not in seen:
            seen.add(_canon(k))
            out.append(r)
    return out
